	protected function icon($key, $class = '', $fallback = 'file') {
		$key = $this->normalizeIcon($key, $fallback);
		$icons = $this->iconPaths();
		$paths = $icons[$key] ?? $icons[$fallback] ?? $icons['file'];
		$class = trim('panorama-icon ' . (string) $class);
		return "<span class='$class' aria-hidden='true'><svg viewBox='0 0 24 24' focusable='false'>$paths</svg></span>";
	}

	protected function fieldIcon($icon, $fallback = 'file') {
		$name = $this->normalizeIcon($icon, '');
		if($name === '') return $this->icon($fallback);
		return "<span class='panorama-icon panorama-field-custom-icon' aria-hidden='true'><span class='fa fa-fw fa-$name'></span></span>";
	}

	protected function tabIcon($key) {
		return $this->icon($key, 'panorama-tab-icon', 'dashboard');
	}
